import json, re
try:
    b = config.get('body')
    if isinstance(b, dict):
        fields = dict()
        for k in list(b.keys()):
            v = b.get(k)
            if v is None or str(v).strip() == '' or '{' in str(v):
                continue
            fields[k] = v
        if 'cardIndex' in fields:
            nums = str(vars.get('card_numbers') or '').split('|')
            digits = re.sub(r'[^0-9]', '', str(fields.pop('cardIndex')))
            i = int(digits or '1') - 1
            if 0 <= i < len(nums) and nums[i]:
                fields['cardNumber'] = nums[i]
            vars['cur_idx'] = str(i + 1)
        if 'newStatementWeek' in fields:
            fields['newStatementWeek'] = re.sub(r'[^0-9]', '', str(fields['newStatementWeek']))
            vars['req_week'] = fields['newStatementWeek']
            if not str(fields.get('statementDay') or '').strip():
                fields['statementDay'] = str(vars.get('cur_statement_day') or '')
        if 'emailAddress' in config.get('body', dict()) or 'currencyType' in fields:
            fields['emailAddress'] = str(vars.get('reg_email') or '')
            if not str(fields.get('statementDate') or '').strip():
                fields['statementDate'] = str(vars.get('stmt_date_' + str(vars.get('cur_idx') or '1')) or vars.get('stmt_date_1') or '')
        call = dict(lang='tr')
        config['body'] = json.dumps(dict(data=fields, call=call))
        h = config.get('headers')
        if not isinstance(h, dict):
            h = dict()
            config['headers'] = h
        h['Content-Type'] = 'application/json'
        h['Accept'] = 'application/json'
except Exception:
    pass

