# Shared reading builder (Turkish). Used in the code node and in the cards.balance post-hook.
import datetime as RD_dt

RD_ONES = ["", "bir", "iki", "üç", "dört", "beş", "altı", "yedi", "sekiz", "dokuz"]
RD_TENS = ["", "on", "yirmi", "otuz", "kırk", "elli", "altmış", "yetmiş", "seksen", "doksan"]
RD_DIG = ["sıfır", "bir", "iki", "üç", "dört", "beş", "altı", "yedi", "sekiz", "dokuz"]
RD_MON = ["Ocak", "Şubat", "Mart", "Nisan", "Mayıs", "Haziran", "Temmuz", "Ağustos", "Eylül", "Ekim", "Kasım", "Aralık"]
RD_CUR = [("debtTL", "Türk Lirası", "lira", "kuruş"), ("debtUSD", "Dolar", "dolar", "sent"),
          ("debtEUR", "Euro", "euro", "sent"), ("debtGBP", "İngiliz Sterlini", "sterlin", "peni")]


def rd_three(n):
    h, r = divmod(n, 100)
    t, o = divmod(r, 10)
    s = []
    if h:
        s.append(("" if h == 1 else RD_ONES[h] + " ") + "yüz")
    if t:
        s.append(RD_TENS[t])
    if o:
        s.append(RD_ONES[o])
    return " ".join(s)


def rd_words(n):
    n = int(n)
    if n == 0:
        return "sıfır"
    parts = []
    for val, name in ((10 ** 9, "milyar"), (10 ** 6, "milyon"), (1000, "bin")):
        q, n = divmod(n, val)
        if q:
            if val == 1000 and q == 1:
                parts.append("bin")
            else:
                parts.append(rd_three(q) + " " + name)
    if n:
        parts.append(rd_three(n))
    return " ".join(parts)


def rd_num(x):
    try:
        return float(str(x).strip())
    except Exception:
        return None


def rd_amount(x, cur):
    v = rd_num(x) or 0.0
    cents = int(round(abs(v) * 100))
    whole, frac = divmod(cents, 100)
    if frac == 0:
        return rd_words(whole) + " " + cur[1]
    return rd_words(whole) + " " + cur[2] + " " + rd_words(frac) + " " + cur[3]


def rd_date(s):
    try:
        p = str(s).strip().split(".")
        return RD_dt.date(int(p[2]), int(p[1]), int(p[0]))
    except Exception:
        return None


def rd_say_date(d):
    return "%d %s %d" % (d.day, RD_MON[d.month - 1], d.year)


def rd_suffix(d):
    y = d.year % 100
    o = y % 10
    t = y // 10
    if o:
        word = RD_ONES[o]
    elif t:
        word = RD_TENS[t]
    else:
        word = "bin"
    vowels = [c for c in word if c in "aeıioöuü"]
    v = vowels[-1] if vowels else "e"
    hv = "ı" if v in "aı" else ("i" if v in "ei" else ("u" if v in "ou" else "ü"))
    cons = "t" if word[-1] in "çfhkpsşt" else "d"
    return "'" + cons + hv + "r"


def rd_cop(text):
    w = str(text).strip().split(" ")[-1].lower()
    vowels = [c for c in w if c in "aeıioöuü"]
    v = vowels[-1] if vowels else "e"
    hv = "ı" if v in "aı" else ("i" if v in "ei" else ("u" if v in "ou" else "ü"))
    cons = "t" if w and w[-1] in "çfhkpsşt" else "d"
    return text + "'" + cons + hv + "r"


def rd_last4(s):
    return " ".join(RD_DIG[int(c)] for c in str(s) if c.isdigit())


def rd_list(names):
    if len(names) == 1:
        return names[0]
    return ", ".join(names[:-1]) + " ve " + names[-1]


def rd_today(now):
    try:
        t = str(now)[:10]
        return RD_dt.date(int(t[0:4]), int(t[5:7]), int(t[8:10]))
    except Exception:
        return None


def rd_reading(bal, last4, name, now):
    """bal: the bank's data object of cards.balance. Returns the exact Turkish reading."""
    today = rd_today(now)
    name = str(name or "").strip()
    if name in ("None", "null"):
        name = ""
    intro = "Sonu " + rd_last4(last4) + " ile biten " + (name + " kartınız" if name else "kartınız")
    sdate = rd_date(bal.get("statementDate"))
    due = rd_date(bal.get("lastPayDate"))
    nsdate = rd_date(bal.get("nextStatementDate"))
    blocks = []
    for cur in RD_CUR:
        b = bal.get(cur[0])
        if isinstance(b, dict) and b:
            blocks.append((cur, b))
    if sdate is None:
        s = intro + " için henüz kesilmiş bir ekstre olmadığından ekstre borcunuz bulunmamaktadır."
        if nsdate is not None:
            s += " İlk hesap kesim tarihiniz " + rd_say_date(nsdate) + " olacak."
        return s
    totals = [(cur, b) for cur, b in blocks if (rd_num(b.get("totalDebt")) or 0) > 0]
    tot_text = ""
    if totals:
        tot_text = "Gelecek dönemler dahil toplam borcunuz " + rd_cop(rd_list([rd_amount(b.get("totalDebt"), cur) for cur, b in totals])) + "."
    else:
        tot_text = "Gelecek dönemler dahil borcunuz bulunmamaktadır."
    if today is not None and nsdate is not None and today == nsdate:
        return intro + " için hesap kesim tarihiniz bugün, ekstreniz saat 00.00 itibarıyla kesilecek. " + tot_text
    auto = ""
    if str(bal.get("automaticPaymentFlag")) == "Y":
        tl = bal.get("debtTL") if isinstance(bal.get("debtTL"), dict) else dict()
        ra = rd_num(tl.get("remainAutomaticPaymentAmount")) or 0
        if ra > 0:
            auto = " Otomatik ödeme talimatınızdan tahsil edilecek kalan tutar " + rd_amount(ra, RD_CUR[0]) + "."
    if today is not None and due is not None and today > due:
        return intro + " için " + rd_say_date(due) + " olan son ödeme tarihiniz geçmiştir. " + tot_text + auto
    if str(bal.get("statementPaymentStatus")) == "NO_DEBT":
        s = intro + "ın " + rd_say_date(sdate) + " tarihli ekstresinden borcunuz bulunmamaktadır. " + tot_text
        if due is not None:
            s += " Son ödeme tarihiniz " + ("bugün" if today == due else rd_say_date(due)) + " olacaktır."
        return s
    lines = []
    clear = []
    for cur, b in blocks:
        rem = rd_num(b.get("remainingDebt")) or 0
        if rem <= 0:
            clear.append(cur[1])
            continue
        st = b.get("statementDebt")
        mn = rd_num(b.get("minPayment")) or 0
        rmn = rd_num(b.get("remainingMinPayment")) or 0
        A = lambda x: rd_amount(x, cur)
        if cur[0] == "debtTL":
            if rmn > 0 and rmn >= mn:
                t = "Türk Lirası borcunuz " + A(st) + ", ödenmesi gereken minimum tutar " + rd_cop(A(mn)) + "."
            elif rmn <= 0:
                t = "Türk Lirası borcunuz " + A(st) + ", kalan toplam borcunuz " + rd_cop(A(rem)) + ". Minimum ödemenizi yaptığınız için teşekkür ederiz."
            else:
                t = ("Türk Lirası borcunuz " + A(st) + ", ödenmesi gereken minimum tutar " + A(mn) + ", kalan toplam borcunuz "
                     + A(rem) + ", kalan minimum ödeme tutarınız " + rd_cop(A(rmn)) + ".")
        else:
            t = cur[1] + " borcunuz " + A(st) + ", kalan toplam borcunuz " + A(rem) + ", ödenmesi gereken minimum tutar " + rd_cop(A(mn)) + "."
        lines.append(t)
    head = intro + "a ait " + rd_say_date(sdate) + " tarihinde kesilen ekstre "
    if lines:
        lines[0] = head + lines[0]
    s = " ".join(lines)
    if clear and lines:
        s += " " + rd_list(clear) + " borcunuz bulunmamaktadır."
    s += auto
    if due is not None:
        if today == due:
            s += " Borçlarınız için son ödeme tarihiniz bugündür."
        else:
            s += " Borçlarınız için son ödeme tarihiniz " + rd_say_date(due) + "'" + rd_cop(rd_words(due.year)).split("'")[1] + "."
    return s.strip()


def rd_after(count, offer):
    if int(count or 0) > 1:
        return "Başka bir kartınızın borcunu öğrenmek ister misiniz?"
    return offer

import json, re
try:
    if isinstance(result, dict):
        result.pop('header', None)
        body = result.get('data')
        if not isinstance(body, dict):
            body = dict()
        inner = body.get('data') if isinstance(body.get('data'), dict) else dict()
        res = body.get('result') if isinstance(body.get('result'), dict) else dict()
        code = str(res.get('code') or res.get('returnCode') or '')
        ok = int(result.get('status_code') or 0) == 200 and str(res.get('returnCode')) == '1' and bool(inner)
        out = dict()
        result['data'] = out
        if ok:
            nm = inner.get('productName')
            reading = rd_reading(inner, inner.get('cardNumberLast4'), nm, vars.get('now'))
            idx = str(vars.get('cur_idx') or '')
            vars['stmt_date_' + idx] = str(inner.get('statementDate') or '')
            out['statementDate'] = str(inner.get('statementDate') or '')
            out['reading'] = reading
            out['what_to_do_next'] = 'Say this reading exactly, word for word, without quotation marks, in one message, then ask the next question per STEP 3: "' + reading + '"'
        else:
            out['what_to_do_next'] = 'SERVICE FAILED. Say exactly: "Şu anda işleminizi gerçekleştiremiyorum, sizi müşteri temsilcimize aktarıyorum." Then call finish_call with route agent.'
except Exception:
    pass

